const referenceLib = String.raw`#![forbid(unsafe_code)]
//! A small terminal guessing game with a pure parser and explicit round state.
//! The stream adapter limits each raw line to 128 bytes before its LF.

use std::error::Error;
use std::fmt;
use std::io::{self, BufRead, Write};

const MIN: u32 = 1;
const MAX: u32 = 100;
const MAX_ATTEMPTS: u8 = 20;
const MAX_RAW_LINE_BYTES: usize = 128;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Input {
    Guess(u32),
    Quit,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum InputError {
    Empty,
    Syntax,
    OutOfRange,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ConfigError {
    Secret,
    Attempts,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum GameError {
    Finished,
    OutOfRange,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Status {
    Active,
    Won,
    Lost,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Feedback {
    Low { remaining: u8 },
    High { remaining: u8 },
    Won { attempts: u8 },
    Lost { secret: u32 },
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SessionOutcome {
    Won,
    Lost,
    Quit,
    Eof,
}

macro_rules! display_error {
    ($type:ident) => {
        impl fmt::Display for $type {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                write!(f, "{self:?}")
            }
        }
        impl Error for $type {}
    };
}
display_error!(InputError);
display_error!(ConfigError);
display_error!(GameError);

pub fn parse_input(line: &str) -> Result<Input, InputError> {
    let line = line.trim();
    if line.is_empty() {
        return Err(InputError::Empty);
    }
    if line == "q" {
        return Ok(Input::Quit);
    }
    if !line.as_bytes().iter().all(u8::is_ascii_digit) {
        return Err(InputError::Syntax);
    }
    match line.parse::<u32>() {
        Ok(value @ MIN..=MAX) => Ok(Input::Guess(value)),
        _ => Err(InputError::OutOfRange),
    }
}

pub struct Game {
    secret: u32,
    attempts: u8,
    remaining: u8,
    status: Status,
}

impl Game {
    pub fn new(secret: u32, attempts: u8) -> Result<Self, ConfigError> {
        if !(MIN..=MAX).contains(&secret) {
            return Err(ConfigError::Secret);
        }
        if attempts == 0 || attempts > MAX_ATTEMPTS {
            return Err(ConfigError::Attempts);
        }
        Ok(Self {
            secret,
            attempts,
            remaining: attempts,
            status: Status::Active,
        })
    }
    pub fn submit(&mut self, guess: u32) -> Result<Feedback, GameError> {
        if self.status != Status::Active {
            return Err(GameError::Finished);
        }
        if !(MIN..=MAX).contains(&guess) {
            return Err(GameError::OutOfRange);
        }
        self.remaining -= 1;
        if guess == self.secret {
            self.status = Status::Won;
            return Ok(Feedback::Won {
                attempts: self.attempts - self.remaining,
            });
        }
        if self.remaining == 0 {
            self.status = Status::Lost;
            return Ok(Feedback::Lost {
                secret: self.secret,
            });
        }
        if guess < self.secret {
            Ok(Feedback::Low {
                remaining: self.remaining,
            })
        } else {
            Ok(Feedback::High {
                remaining: self.remaining,
            })
        }
    }
    pub fn status(&self) -> Status {
        self.status
    }
    pub fn remaining(&self) -> u8 {
        self.remaining
    }
}

pub fn new_game_with(attempts: u8, draw: impl FnOnce() -> u32) -> Result<Game, ConfigError> {
    if attempts == 0 || attempts > MAX_ATTEMPTS {
        return Err(ConfigError::Attempts);
    }
    Game::new(draw(), attempts)
}

fn invalid_data(message: &str) -> io::Error {
    io::Error::new(io::ErrorKind::InvalidData, message)
}
fn read_raw_line<R: BufRead>(reader: &mut R) -> io::Result<Option<Vec<u8>>> {
    let mut bytes = Vec::with_capacity(MAX_RAW_LINE_BYTES + 1);
    let mut limited = std::io::Read::take(reader, (MAX_RAW_LINE_BYTES + 1) as u64);
    let count = limited.read_until(b'\n', &mut bytes)?;
    if count == 0 {
        return Ok(None);
    }
    if bytes.len() == MAX_RAW_LINE_BYTES + 1 && bytes.last() != Some(&b'\n') {
        return Err(invalid_data("input line exceeds 128 bytes"));
    }
    if bytes.len() == MAX_RAW_LINE_BYTES + 1 && bytes.last() == Some(&b'\n') {
        return Ok(Some(bytes));
    }
    Ok(Some(bytes))
}
fn finish<W: Write>(
    writer: &mut W,
    text: &str,
    outcome: SessionOutcome,
) -> io::Result<SessionOutcome> {
    writer.write_all(text.as_bytes())?;
    writer.flush()?;
    Ok(outcome)
}

pub fn play<R: BufRead, W: Write>(
    reader: &mut R,
    writer: &mut W,
    mut game: Game,
) -> io::Result<SessionOutcome> {
    if game.status() != Status::Active {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "game is already finished",
        ));
    }
    writer.write_all(
        format!(
            "Number Guessing+: 1..100; attempts={}. Enter q to quit.\n",
            game.remaining()
        )
        .as_bytes(),
    )?;
    loop {
        writer.write_all(b"guess> ")?;
        writer.flush()?;
        let Some(bytes) = read_raw_line(reader)? else {
            return finish(writer, "End of input.\n", SessionOutcome::Eof);
        };
        let line = std::str::from_utf8(&bytes).map_err(|_| invalid_data("input is not UTF-8"))?;
        match parse_input(line) {
            Err(_) => writer.write_all(b"Invalid input. Enter a number from 1 to 100 or q.\n")?,
            Ok(Input::Quit) => return finish(writer, "Quit.\n", SessionOutcome::Quit),
            Ok(Input::Guess(guess)) => match game
                .submit(guess)
                .expect("active game accepts a parsed in-range guess")
            {
                Feedback::Low { remaining } => {
                    writer.write_all(format!("Too low; remaining={remaining}.\n").as_bytes())?
                }
                Feedback::High { remaining } => {
                    writer.write_all(format!("Too high; remaining={remaining}.\n").as_bytes())?
                }
                Feedback::Won { attempts } => {
                    return finish(
                        writer,
                        &format!("Won in {attempts} attempts.\n"),
                        SessionOutcome::Won,
                    );
                }
                Feedback::Lost { secret } => {
                    return finish(
                        writer,
                        &format!("Lost; secret={secret}.\n"),
                        SessionOutcome::Lost,
                    );
                }
            },
        }
    }
}
`;

