const referenceMain = String.raw`use number_guessing::{new_game_with, play};
use std::io::{self, BufReader};

const USAGE: &str = "Usage: number-guessing [--attempts N] [--secret N]";

fn decimal(value: &str) -> Option<u32> {
    (!value.is_empty() && value.as_bytes().iter().all(u8::is_ascii_digit))
        .then(|| value.parse().ok())
        .flatten()
}
fn config() -> Result<Option<(u8, Option<u32>)>, String> {
    let arguments: Vec<String> = std::env::args().skip(1).collect();
    if arguments.len() == 1 && arguments[0] == "--help" {
        return Ok(None);
    }
    let mut attempts = 6u8;
    let mut saw_attempts = false;
    let mut secret = None;
    let mut index = 0;
    while index < arguments.len() {
        let flag = &arguments[index];
        if flag != "--attempts" && flag != "--secret" {
            return Err(USAGE.into());
        }
        index += 1;
        let Some(value) = arguments.get(index).and_then(|value| decimal(value)) else {
            return Err(USAGE.into());
        };
        match flag.as_str() {
            "--attempts" if saw_attempts => return Err(USAGE.into()),
            "--attempts" if !(1..=20).contains(&value) => return Err(USAGE.into()),
            "--attempts" => {
                attempts = value as u8;
                saw_attempts = true;
            }
            "--secret" if secret.is_some() || !(1..=100).contains(&value) => {
                return Err(USAGE.into());
            }
            "--secret" => secret = Some(value),
            _ => return Err(USAGE.into()),
        }
        index += 1;
    }
    Ok(Some((attempts, secret)))
}
fn main() {
    let Some((attempts, secret)) = (match config() {
        Ok(value) => value,
        Err(error) => {
            eprintln!("{error}");
            std::process::exit(2);
        }
    }) else {
        println!("{USAGE}");
        return;
    };
    let game = match new_game_with(attempts, || {
        secret.unwrap_or_else(|| rand::random_range(1..=100))
    }) {
        Ok(game) => game,
        Err(error) => {
            eprintln!("{error}");
            std::process::exit(2);
        }
    };
    let stdin = io::stdin();
    let mut input = BufReader::new(stdin.lock());
    let mut output = io::stdout().lock();
    match play(&mut input, &mut output, game) {
        Ok(number_guessing::SessionOutcome::Won) => {}
        Ok(_) => std::process::exit(1),
        Err(error) => {
            eprintln!("{error}");
            std::process::exit(2);
        }
    }
}
`;

const contracts = String.raw`use number_guessing::*;
use std::cell::Cell;
use std::io::{self, BufRead, BufReader, Cursor, Read, Write};
use std::rc::Rc;

#[test]
fn parser_accepts_only_q_or_ascii_digits_in_range() {
    assert_eq!(parse_input("1"), Ok(Input::Guess(1)));
    assert_eq!(parse_input("100"), Ok(Input::Guess(100)));
    assert_eq!(parse_input("  007\r\n"), Ok(Input::Guess(7)));
    assert_eq!(parse_input(" q "), Ok(Input::Quit));
    assert_eq!(parse_input("\u{2003}"), Err(InputError::Empty));
    assert_eq!(parse_input("0"), Err(InputError::OutOfRange));
    assert_eq!(parse_input("+7"), Err(InputError::Syntax));
    assert_eq!(parse_input("-7"), Err(InputError::Syntax));
    assert_eq!(parse_input("７"), Err(InputError::Syntax));
    assert_eq!(parse_input("1.0"), Err(InputError::Syntax));
    assert_eq!(parse_input("7 8"), Err(InputError::Syntax));
    assert_eq!(parse_input("101"), Err(InputError::OutOfRange));
    assert_eq!(
        parse_input("999999999999999999999999"),
        Err(InputError::OutOfRange)
    );
}

#[test]
fn state_keeps_invalid_guesses_and_prioritizes_a_final_win() {
    assert!(matches!(Game::new(0, 1), Err(ConfigError::Secret)));
    assert!(matches!(Game::new(101, 1), Err(ConfigError::Secret)));
    assert!(matches!(Game::new(1, 0), Err(ConfigError::Attempts)));
    assert!(matches!(Game::new(1, 21), Err(ConfigError::Attempts)));
    assert_eq!(Game::new(100, 20).unwrap().remaining(), 20);
    let mut game = Game::new(42, 1).unwrap();
    assert_eq!(game.submit(0), Err(GameError::OutOfRange));
    assert_eq!(game.remaining(), 1);
    assert_eq!(game.submit(42), Ok(Feedback::Won { attempts: 1 }));
    assert_eq!(game.status(), Status::Won);
    assert_eq!(game.submit(42), Err(GameError::Finished));
}

#[test]
fn lost_games_are_terminal_before_range_validation_and_immutable() {
    let mut game = Game::new(42, 1).unwrap();
    assert_eq!(game.submit(41), Ok(Feedback::Lost { secret: 42 }));
    assert_eq!(game.status(), Status::Lost);
    assert_eq!(game.remaining(), 0);
    assert_eq!(game.submit(0), Err(GameError::Finished));
    assert_eq!(game.remaining(), 0);
}

#[test]
fn draw_is_called_once_only_after_attempt_validation() {
    let mut calls = 0;
    assert!(matches!(
        new_game_with(0, || {
            calls += 1;
            7
        }),
        Err(ConfigError::Attempts)
    ));
    assert_eq!(calls, 0);
    let game = new_game_with(2, || {
        calls += 1;
        7
    })
    .unwrap();
    assert_eq!(calls, 1);
    assert_eq!(game.remaining(), 2);
}

#[test]
fn draw_rejects_twenty_one_without_calling_and_preserves_secret_errors() {
    let mut calls = 0;
    assert!(matches!(
        new_game_with(21, || {
            calls += 1;
            42
        }),
        Err(ConfigError::Attempts)
    ));
    assert_eq!(calls, 0);
    let game = new_game_with(20, || {
        calls += 1;
        101
    });
    assert!(matches!(game, Err(ConfigError::Secret)));
    assert_eq!(calls, 1);
}

#[test]
fn stream_preserves_attempts_and_handles_crlf_and_final_eof() {
    let mut reader = BufReader::new(Cursor::new(b"bad\r\n41\n42"));
    let mut output = Vec::new();
    assert_eq!(
        play(&mut reader, &mut output, Game::new(42, 2).unwrap()).unwrap(),
        SessionOutcome::Won
    );
    assert_eq!(
        String::from_utf8(output).unwrap(),
        "Number Guessing+: 1..100; attempts=2. Enter q to quit.\nguess> Invalid input. Enter a number from 1 to 100 or q.\nguess> Too low; remaining=1.\nguess> Won in 2 attempts.\n"
    );
}

#[test]
fn session_keeps_initial_secret_through_invalid_low_and_high_guesses() {
    let mut reader = BufReader::new(Cursor::new(b"oops\n43\n41\n42\n"));
    let mut output = Vec::new();
    assert_eq!(
        play(&mut reader, &mut output, Game::new(42, 3).unwrap()).unwrap(),
        SessionOutcome::Won
    );
    assert_eq!(
        String::from_utf8(output).unwrap(),
        "Number Guessing+: 1..100; attempts=3. Enter q to quit.\nguess> Invalid input. Enter a number from 1 to 100 or q.\nguess> Too high; remaining=2.\nguess> Too low; remaining=1.\nguess> Won in 3 attempts.\n"
    );
}

#[test]
fn empty_line_is_invalid_but_empty_input_is_eof() {
    let mut reader = BufReader::new(Cursor::new(b"\nq\n"));
    let mut output = Vec::new();
    assert_eq!(
        play(&mut reader, &mut output, Game::new(42, 1).unwrap()).unwrap(),
        SessionOutcome::Quit
    );
    assert_eq!(
        String::from_utf8(output).unwrap(),
        "Number Guessing+: 1..100; attempts=1. Enter q to quit.\nguess> Invalid input. Enter a number from 1 to 100 or q.\nguess> Quit.\n"
    );

    let mut reader = BufReader::new(Cursor::new(Vec::<u8>::new()));
    let mut output = Vec::new();
    assert_eq!(
        play(&mut reader, &mut output, Game::new(42, 1).unwrap()).unwrap(),
        SessionOutcome::Eof
    );
    assert_eq!(
        String::from_utf8(output).unwrap(),
        "Number Guessing+: 1..100; attempts=1. Enter q to quit.\nguess> End of input.\n"
    );
}

#[test]
fn terminal_games_are_rejected_before_any_output() {
    let mut game = Game::new(42, 1).unwrap();
    assert_eq!(game.submit(42), Ok(Feedback::Won { attempts: 1 }));
    let mut output = Vec::new();
    let error = play(&mut BufReader::new(Cursor::new(b"")), &mut output, game).unwrap_err();
    assert_eq!(error.kind(), io::ErrorKind::InvalidInput);
    assert!(output.is_empty());
}

struct ChunkedReader {
    input: Cursor<Vec<u8>>,
    chunk: usize,
    exposed: Rc<Cell<usize>>,
}

impl Read for ChunkedReader {
    fn read(&mut self, buffer: &mut [u8]) -> io::Result<usize> {
        let amount = buffer.len().min(self.chunk);
        let read = self.input.read(&mut buffer[..amount])?;
        self.exposed.set(self.exposed.get() + read);
        Ok(read)
    }
}

impl BufRead for ChunkedReader {
    fn fill_buf(&mut self) -> io::Result<&[u8]> {
        let chunk = self.chunk;
        let input = self.input.fill_buf()?;
        let amount = input.len().min(chunk);
        self.exposed.set(self.exposed.get() + amount);
        Ok(&input[..amount])
    }

    fn consume(&mut self, amount: usize) {
        self.input.consume(amount);
    }
}

#[test]
fn raw_line_boundary_accepts_128_bytes_and_reads_at_most_129() {
    let exposed = Rc::new(Cell::new(0));
    let mut valid = vec![b'0'; 126];
    valid.extend_from_slice(b"1\r\n");
    let mut reader = ChunkedReader {
        input: Cursor::new(valid),
        chunk: 3,
        exposed: Rc::clone(&exposed),
    };
    let mut output = Vec::new();
    assert_eq!(
        play(&mut reader, &mut output, Game::new(1, 1).unwrap()).unwrap(),
        SessionOutcome::Won
    );
    assert_eq!(exposed.get(), 129);

    let exposed = Rc::new(Cell::new(0));
    let mut overlong = vec![b'0'; 127];
    overlong.extend_from_slice(b"1\r\n");
    let mut reader = ChunkedReader {
        input: Cursor::new(overlong),
        chunk: 3,
        exposed: Rc::clone(&exposed),
    };
    let mut output = Vec::new();
    assert_eq!(
        play(&mut reader, &mut output, Game::new(1, 1).unwrap())
            .unwrap_err()
            .kind(),
        io::ErrorKind::InvalidData
    );
    assert_eq!(exposed.get(), 129);
}

#[test]
fn stream_rejects_overlong_or_non_utf8_input_without_faking_a_guess() {
    let mut output = Vec::new();
    let mut overlong = BufReader::new(Cursor::new(vec![b'x'; 129]));
    assert_eq!(
        play(&mut overlong, &mut output, Game::new(5, 1).unwrap())
            .unwrap_err()
            .kind(),
        io::ErrorKind::InvalidData
    );
    let mut invalid = BufReader::new(Cursor::new(vec![0xff, b'\n']));
    assert_eq!(
        play(&mut invalid, &mut Vec::new(), Game::new(5, 1).unwrap())
            .unwrap_err()
            .kind(),
        io::ErrorKind::InvalidData
    );
}

struct FlushProbe {
    bytes: Vec<u8>,
    flushed: bool,
}
impl Write for FlushProbe {
    fn write(&mut self, input: &[u8]) -> io::Result<usize> {
        self.bytes.extend_from_slice(input);
        Ok(input.len())
    }
    fn flush(&mut self) -> io::Result<()> {
        self.flushed = true;
        Ok(())
    }
}
#[test]
fn prompt_is_flushed_before_a_read_and_terminal_output_is_flushed() {
    let mut output = FlushProbe {
        bytes: Vec::new(),
        flushed: false,
    };
    let mut input = BufReader::new(Cursor::new(b"q\n"));
    assert_eq!(
        play(&mut input, &mut output, Game::new(5, 1).unwrap()).unwrap(),
        SessionOutcome::Quit
    );
    assert!(output.flushed);
    assert!(
        String::from_utf8(output.bytes)
            .unwrap()
            .contains("guess> Quit.")
    );
}

struct FlushOrderingWriter {
    dirty: Rc<Cell<bool>>,
    flushes: usize,
    bytes: Vec<u8>,
}

impl Write for FlushOrderingWriter {
    fn write(&mut self, input: &[u8]) -> io::Result<usize> {
        self.bytes.extend_from_slice(input);
        self.dirty.set(true);
        Ok(input.len())
    }

    fn flush(&mut self) -> io::Result<()> {
        self.dirty.set(false);
        self.flushes += 1;
        Ok(())
    }
}

struct FlushOrderingReader {
    dirty: Rc<Cell<bool>>,
    reads: usize,
    input: Cursor<Vec<u8>>,
}

impl Read for FlushOrderingReader {
    fn read(&mut self, buffer: &mut [u8]) -> io::Result<usize> {
        assert!(!self.dirty.get(), "read happened before prompt flush");
        self.reads += 1;
        self.input.read(buffer)
    }
}

impl BufRead for FlushOrderingReader {
    fn fill_buf(&mut self) -> io::Result<&[u8]> {
        assert!(!self.dirty.get(), "read happened before prompt flush");
        self.reads += 1;
        self.input.fill_buf()
    }

    fn consume(&mut self, amount: usize) {
        self.input.consume(amount);
    }
}

#[test]
fn prompt_flush_is_observed_before_the_first_read() {
    let dirty = Rc::new(Cell::new(false));
    let mut reader = FlushOrderingReader {
        dirty: Rc::clone(&dirty),
        reads: 0,
        input: Cursor::new(b"q\n".to_vec()),
    };
    let mut writer = FlushOrderingWriter {
        dirty: Rc::clone(&dirty),
        flushes: 0,
        bytes: Vec::new(),
    };

    assert_eq!(
        play(&mut reader, &mut writer, Game::new(42, 1).unwrap()).unwrap(),
        SessionOutcome::Quit
    );
    assert_eq!(reader.reads, 1);
    assert!(
        writer.flushes >= 2,
        "prompt and terminal output should both flush"
    );
}

struct FailingReader;

impl Read for FailingReader {
    fn read(&mut self, _buffer: &mut [u8]) -> io::Result<usize> {
        Err(io::Error::other("read failure"))
    }
}

impl BufRead for FailingReader {
    fn fill_buf(&mut self) -> io::Result<&[u8]> {
        Err(io::Error::other("read failure"))
    }

    fn consume(&mut self, _amount: usize) {}
}

struct FailingWriter {
    fail_writes: bool,
    fail_flushes: bool,
}

impl Write for FailingWriter {
    fn write(&mut self, _input: &[u8]) -> io::Result<usize> {
        if self.fail_writes {
            Err(io::Error::other("write failure"))
        } else {
            Ok(_input.len())
        }
    }

    fn flush(&mut self) -> io::Result<()> {
        if self.fail_flushes {
            Err(io::Error::other("flush failure"))
        } else {
            Ok(())
        }
    }
}

#[test]
fn read_write_and_prompt_flush_errors_are_preserved() {
    let mut reader = BufReader::new(FailingReader);
    let mut writer = Vec::new();
    let error = play(&mut reader, &mut writer, Game::new(42, 1).unwrap()).unwrap_err();
    assert_eq!(error.kind(), io::ErrorKind::Other);
    assert_eq!(error.to_string(), "read failure");

    let mut reader = BufReader::new(Cursor::new(b"q\n"));
    let mut writer = FailingWriter {
        fail_writes: true,
        fail_flushes: false,
    };
    let error = play(&mut reader, &mut writer, Game::new(42, 1).unwrap()).unwrap_err();
    assert_eq!(error.kind(), io::ErrorKind::Other);
    assert_eq!(error.to_string(), "write failure");

    let mut reader = BufReader::new(Cursor::new(b"q\n"));
    let mut writer = FailingWriter {
        fail_writes: false,
        fail_flushes: true,
    };
    let error = play(&mut reader, &mut writer, Game::new(42, 1).unwrap()).unwrap_err();
    assert_eq!(error.kind(), io::ErrorKind::Other);
    assert_eq!(error.to_string(), "flush failure");
}

struct FlushCountWriter {
    bytes: Vec<u8>,
    flushes: usize,
}

impl Write for FlushCountWriter {
    fn write(&mut self, input: &[u8]) -> io::Result<usize> {
        self.bytes.extend_from_slice(input);
        Ok(input.len())
    }

    fn flush(&mut self) -> io::Result<()> {
        self.flushes += 1;
        Ok(())
    }
}

#[test]
fn every_terminal_outcome_flushes_its_final_message() {
    let cases = [
        (
            Game::new(42, 1).unwrap(),
            b"42\n".as_slice(),
            SessionOutcome::Won,
        ),
        (
            Game::new(42, 1).unwrap(),
            b"41\n".as_slice(),
            SessionOutcome::Lost,
        ),
        (
            Game::new(42, 1).unwrap(),
            b"q\n".as_slice(),
            SessionOutcome::Quit,
        ),
        (
            Game::new(42, 1).unwrap(),
            b"".as_slice(),
            SessionOutcome::Eof,
        ),
    ];
    for (game, input, outcome) in cases {
        let mut reader = BufReader::new(Cursor::new(input));
        let mut writer = FlushCountWriter {
            bytes: Vec::new(),
            flushes: 0,
        };
        assert_eq!(play(&mut reader, &mut writer, game).unwrap(), outcome);
        assert!(writer.flushes >= 2, "prompt and terminal output must flush");
    }
}
`;

const cliTests = String.raw`use std::io::{Read, Write};
use std::process::{Child, Command, ExitStatus, Stdio};
use std::sync::mpsc::{Receiver, RecvTimeoutError, sync_channel};
use std::thread::JoinHandle;
use std::time::{Duration, Instant};

fn bin() -> &'static str {
    env!("CARGO_BIN_EXE_number-guessing")
}

struct ChildGuard {
    child: Child,
}

impl ChildGuard {
    fn wait_bounded(&mut self) -> ExitStatus {
        let deadline = Instant::now() + Duration::from_secs(5);
        loop {
            if let Some(status) = self.child.try_wait().unwrap() {
                return status;
            }
            if Instant::now() >= deadline {
                let _ = self.child.kill();
                let _ = self.child.wait();
                panic!("child did not finish within five seconds");
            }
            std::thread::sleep(Duration::from_millis(10));
        }
    }
}

impl Drop for ChildGuard {
    fn drop(&mut self) {
        if self.child.try_wait().unwrap().is_none() {
            let _ = self.child.kill();
        }
        let _ = self.child.wait();
    }
}

fn run(arguments: &[&str], input: &str) -> std::process::Output {
    let child = Command::new(bin())
        .args(arguments)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();
    let mut guard = ChildGuard { child };
    guard
        .child
        .stdin
        .take()
        .unwrap()
        .write_all(input.as_bytes())
        .unwrap();
    let status = guard.wait_bounded();
    let mut stdout = Vec::new();
    guard
        .child
        .stdout
        .take()
        .unwrap()
        .read_to_end(&mut stdout)
        .unwrap();
    let mut stderr = Vec::new();
    guard
        .child
        .stderr
        .take()
        .unwrap()
        .read_to_end(&mut stderr)
        .unwrap();
    let output = std::process::Output {
        status,
        stdout,
        stderr,
    };
    if String::from_utf8_lossy(&output.stderr).contains("not yet implemented") {
        panic!("not yet implemented: the starter CLI adapter is unfinished");
    }
    output
}

#[test]
fn practice_transcripts_and_bad_configuration_are_exact() {
    let won = run(&["--attempts", "3", "--secret", "42"], "43\n41\n42\n");
    assert_eq!(won.status.code(), Some(0));
    assert_eq!(
        String::from_utf8(won.stdout).unwrap(),
        "Number Guessing+: 1..100; attempts=3. Enter q to quit.\nguess> Too high; remaining=2.\nguess> Too low; remaining=1.\nguess> Won in 3 attempts.\n"
    );
    let lost = run(&["--secret", "42", "--attempts", "2"], "41\n43\n");
    assert_eq!(lost.status.code(), Some(1));
    assert_eq!(
        String::from_utf8(lost.stdout).unwrap(),
        "Number Guessing+: 1..100; attempts=2. Enter q to quit.\nguess> Too low; remaining=1.\nguess> Lost; secret=42.\n"
    );
    let quit = run(&["--secret", "42"], "q\n");
    assert_eq!(quit.status.code(), Some(1));
    assert_eq!(
        String::from_utf8(quit.stdout).unwrap(),
        "Number Guessing+: 1..100; attempts=6. Enter q to quit.\nguess> Quit.\n"
    );
    let eof = run(&["--secret", "42"], "");
    assert_eq!(eof.status.code(), Some(1));
    assert_eq!(
        String::from_utf8(eof.stdout).unwrap(),
        "Number Guessing+: 1..100; attempts=6. Enter q to quit.\nguess> End of input.\n"
    );
    let bad = run(&["--attempts", "0"], "");
    assert_eq!(bad.status.code(), Some(2));
    assert!(bad.stdout.is_empty());

    for arguments in [
        &["--attempts", "21"][..],
        &["--attempts", "1", "--attempts", "2"][..],
        &["--secret", "101"][..],
        &["--secret", "1", "--secret", "2"][..],
        &["--secret"][..],
        &["--secret", "+1"][..],
        &["--unknown", "1"][..],
        &["42"][..],
        &["--help", "--secret", "42"][..],
    ] {
        let bad = run(arguments, "");
        assert_eq!(bad.status.code(), Some(2), "arguments: {arguments:?}");
        assert!(bad.stdout.is_empty(), "arguments: {arguments:?}");
    }
    let help = run(&["--help"], "");
    assert_eq!(help.status.code(), Some(0));
    assert_eq!(
        help.stdout,
        b"Usage: number-guessing [--attempts N] [--secret N]\n"
    );
    assert!(help.stderr.is_empty());
}

struct OutputReader {
    receiver: Option<Receiver<Vec<u8>>>,
    join: Option<JoinHandle<()>>,
}

impl OutputReader {
    fn new(mut reader: impl Read + Send + 'static) -> Self {
        let (sender, receiver) = sync_channel(8);
        let join = std::thread::spawn(move || {
            let mut buffer = [0; 256];
            loop {
                match reader.read(&mut buffer) {
                    Ok(0) | Err(_) => break,
                    Ok(amount) => {
                        if sender.send(buffer[..amount].to_vec()).is_err() {
                            break;
                        }
                    }
                }
            }
        });
        Self {
            receiver: Some(receiver),
            join: Some(join),
        }
    }

    fn receive_until(&self, markers: &[&[u8]]) -> String {
        let deadline = Instant::now() + Duration::from_secs(5);
        let mut bytes = Vec::new();
        loop {
            let remaining = deadline.saturating_duration_since(Instant::now());
            if remaining.is_zero() {
                panic!("child produced no expected output within five seconds");
            }
            match self.receiver.as_ref().unwrap().recv_timeout(remaining) {
                Ok(chunk) => {
                    bytes.extend_from_slice(&chunk);
                    assert!(bytes.len() <= 32 * 1024, "child output exceeded test bound");
                    if markers.iter().any(|marker| bytes.ends_with(marker)) {
                        return String::from_utf8(bytes).unwrap();
                    }
                }
                Err(RecvTimeoutError::Timeout) => {
                    panic!("child produced no expected output within five seconds");
                }
                Err(RecvTimeoutError::Disconnected) => {
                    panic!("child output closed before the expected marker");
                }
            }
        }
    }
}

impl Drop for OutputReader {
    fn drop(&mut self) {
        drop(self.receiver.take());
        if let Some(join) = self.join.take() {
            let _ = join.join();
        }
    }
}
#[test]
fn dropping_output_reader_disconnects_a_full_channel_before_joining() {
    struct Flood {
        reads: usize,
        saturated: std::sync::mpsc::Sender<()>,
    }
    impl Read for Flood {
        fn read(&mut self, buffer: &mut [u8]) -> std::io::Result<usize> {
            self.reads += 1;
            if self.reads == 9 {
                self.saturated.send(()).unwrap();
            }
            buffer.fill(b'x');
            Ok(buffer.len())
        }
    }
    let (saturated, ready) = std::sync::mpsc::channel();
    let (finished, done) = std::sync::mpsc::channel();
    let owner = std::thread::spawn(move || {
        let output = OutputReader::new(Flood {
            reads: 0,
            saturated,
        });
        ready.recv_timeout(Duration::from_secs(2)).unwrap();
        drop(output);
        finished.send(()).unwrap();
    });
    assert!(
        done.recv_timeout(Duration::from_secs(3)).is_ok(),
        "reader teardown must disconnect a full channel before joining"
    );
    owner.join().unwrap();
}

#[test]
fn ordinary_play_draws_a_secret_and_an_adaptive_bisection_wins_within_seven_guesses() {
    let mut child = Command::new(bin())
        .args(["--attempts", "7"])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();
    let stdout = child.stdout.take().unwrap();
    let output = OutputReader::new(stdout);
    let mut guard = ChildGuard { child };
    let mut stdin = guard.child.stdin.take().unwrap();
    let mut low = 1u32;
    let mut high = 100u32;
    let mut transcript = output.receive_until(&[b"guess> "]);
    for _ in 0..7 {
        let guess = (low + high) / 2;
        writeln!(stdin, "{guess}").unwrap();
        stdin.flush().unwrap();
        let response = output.receive_until(&[b"attempts.\n", b"guess> "]);
        transcript.push_str(&response);
        if response.contains("Won in") {
            break;
        }
        if response.contains("Too low") {
            low = guess + 1;
        } else if response.contains("Too high") {
            high = guess - 1;
        } else {
            panic!("unexpected response: {response}");
        }
    }
    drop(stdin);
    let status = guard.wait_bounded();
    assert_eq!(status.code(), Some(0), "{transcript}");
    drop(guard);
    assert!(transcript.contains("Won in"), "{transcript}");
}
`;

const readme = String.raw`# Number Guessing+

Uruchom zwykłą grę z losowym sekretem:

    cargo run --locked --

Dla każdej gry losowana jest jedna liczba od 1 do 100. To nie jest obietnica kryptograficznej
losowości ani powtarzalnej sekwencji między wersjami rand.

Aby uzyskać powtarzalny transkrypt ćwiczenia, użyj:

    cargo run --locked -- --secret 42

Opcja --attempts N ustawia od jednej do dwudziestu prób; domyślnie jest ich sześć.
Błędna konfiguracja wypisuje usage na stderr i kończy program kodem 2 przed startem gry.

Biblioteka przyjmuje tylko dziesiętne cyfry ASCII albo małą literę q, rozdziela błędy
parsera od błędów I/O i ogranicza surową linię do 128 bajtów przed LF. Niepoprawny tekst lub liczba poza zakresem
nie zużywa próby. Adapter strumienia ogranicza własny odczyt, ale nie może ograniczyć
alokacji wykonanych wewnątrz dowolnego BufRead przekazanego przez wywołującego.

Sprawdzenia: cargo fmt --check, cargo check --locked, cargo test --locked, cargo test --doc --locked oraz cargo clippy --all-targets -- -D warnings.

Źródła przejrzane 2026-09-13: rozdział Rust Book o grze w zgadywanie, manifest rand
0.10.2 oraz dokumentacja random_range/ThreadRng i książka o powtarzalności Rust Rand.
`;

const design = String.raw`# Projekt i granice

Parser jest czysty. Game posiada sekret i stan, a play jako jedyny komponent łączy
buforowane wejście z wyjściem terminala. Po sprawdzeniu liczby prób poprawny draw
wykonuje się dokładnie raz; błędne i niepoprawne strzały nigdy nie losują ponownie.

Wejście jest odczytywane najwyżej po 129 bajtów, aby wykryć zbyt długą linię bez
czytania jej reszty. Ogranicza to tymczasowy bufor tego adaptera. Własny BufRead
może wcześniej zaalokować więcej pamięci wewnątrz swojej implementacji. Zapisy i
flush terminala są przekazywane jako błędy I/O; dane zapisane przed błędem pozostają
obserwowalne.
`;

